INSERT INTO mosaics (id, name, school, subgroup, tier, status_state, cost_pattern, source, definition) VALUES ('alap-magia-leplezese', 'Mágia leplezése', 'alapvarazslatok', NULL, 0, 'complete', 'flat', 'Part 2', '{"id": "alap-magia-leplezese", "name": "Mágia leplezése", "school": "alapvarazslatok", "tier": 0, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "casting", "time": {"kind": "time", "amounts": {"kor": 1}}}, "duration": {"kind": "time", "time": {"kind": "time", "amounts": {"kor": 1}}}, "range": {"kind": "zone"}, "resistance": {"kind": "none"}, "power": {"unit": "E", "baseE": 1, "step": {"mp": 1, "e": 1}}, "cost": {"pattern": "flat", "baseMp": 1}, "inputs": [], "source": "Part 2"}'::jsonb);
INSERT INTO mosaics (id, name, school, subgroup, tier, status_state, cost_pattern, source, definition) VALUES ('anyagi-elemi-oselem-idezese', 'Őselem idézése', 'anyagi', 'elemi', 2, 'complete', 'flat', 'Part 10a', '{"id": "anyagi-elemi-oselem-idezese", "name": "Őselem idézése", "school": "anyagi", "subgroup": "elemi", "tier": 2, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "casting", "time": {"kind": "time", "amounts": {"sz": 1}}}, "duration": {"kind": "formDependent"}, "range": {"kind": "zone"}, "resistance": {"kind": "oppositeElement", "input": "element", "pairs": {"ostuz": "osviz", "osviz": "ostuz", "osfold": "oslevego", "oslevego": "osfold"}}, "power": {"unit": "E", "baseE": 1, "step": {"mp": 1, "e": 1}}, "cost": {"pattern": "flat", "baseMp": 1}, "inputs": [{"id": "element", "label": "Őselem", "type": "choice", "values": ["ostuz", "osviz", "osfold", "oslevego"], "labels": {"ostuz": "Ős tűz", "osviz": "Ős víz", "osfold": "Ős föld", "oslevego": "Ős levegő"}, "descriptions": {"ostuz": "Önállóan létező anyag, így a természetes tűzzel ellentétben nem kell semmi, ami táplálja. A belsejében az erősségénél tizenötször nagyobb erősségű elemi hő van (kb. 80°+20°/tűz-E). A környezetbe szétsugárzott hő viszont már normális, és a fénye sem elemi fény (belül sem).", "osviz": "Teljesen tiszta átlátszó víz. Megidézésekor a környezet hőmérsékletét veszi fel (nem jön vele az elemi hideg paraelem).", "osfold": "Tökéletesen száraz, szürkés, porszerű anyag. Szemcséinek a mérete a homokéhoz hasonló. A normál levegőt is kiszorítja, így a légzés benne nehézkesebbé válik.", "oslevego": "Tiszta levegő. Belélegezhető. Nem kíséri hő hatás (környezet hőmérséklete) a megidézésekor. A füst, légimérgek és egyéb anyagokat kiszorítja onnan, ahol van."}}, {"id": "form", "label": "Forma", "type": "form"}], "effect": "A varázsló őselemet teremt, amit a kívánt formába zár (formázás). Ez lehet a Hat Iskolaforma egyike, vagy – ha a varázsló bír efféle tudással – valamely Szabálytalan Elemi Forma. Azt, hogy a teremtett őselem meddig marad együtt, a formázás határozza meg. Az ellentétes őselemek gyengítik, akár ki is oltják egymást. A varázslók az őstüzet általában támadásra, az ősvizet általában védekezésre használják, míg a további két őselemhez egyéb céllal, vagy más létsíkok teremtményeivel szemben nyúlnak.", "source": "Part 10a"}'::jsonb);
INSERT INTO mosaics (id, name, school, subgroup, tier, status_state, cost_pattern, source, definition) VALUES ('anyagi-elemi-paraelem-idezese', 'Paraelem idézése', 'anyagi', 'elemi', 3, 'complete', 'flat', 'Part 10a', '{"id": "anyagi-elemi-paraelem-idezese", "name": "Paraelem idézése", "school": "anyagi", "subgroup": "elemi", "tier": 3, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "casting", "time": {"kind": "time", "amounts": {"sz": 1}}}, "duration": {"kind": "formDependent"}, "range": {"kind": "zone"}, "resistance": {"kind": "givenParaElement", "input": "paraElement"}, "power": {"unit": "E", "baseE": 1, "step": {"mp": 1, "e": 1}}, "cost": {"pattern": "flat", "baseMp": 1}, "inputs": [{"id": "paraElement", "label": "Paraelem", "type": "choice", "values": ["ho", "fagy", "feny", "setet"], "labels": {"ho": "Elemi hő", "fagy": "Elemi hideg", "feny": "Elemi fény", "setet": "Elemi sötétség"}, "descriptions": {"ho": "A tűz és a föld paraeleme. Megidézve minden természetes élettelen anyagot egy szempillantás alatt felmelegít az erősségnek megfelelő hőmérsékletre. Ellentétes paraeleme az elemi hideg.\n\nHő teremtése: A varázsló elemi hőt teremt, és a kívánt formába önti. A hőmérséklet az adott formán belül eső területen E-nként 10 °C, függetlenül a természetes hőmérséklettől – akár sebez is, a formán túl ellenben egyáltalán nem érződik. A sebzés körönként 100 °C-nál 1 Sp (sebzés pont), és minden további teljes 20 °C-onként 1 Sp-vel nő.", "fagy": "A levegő és a víz paraeleme. Megidézve minden természetes élettelen anyagot egy szempillantás alatt lehűt az erősségnek megfelelő hőmérsékletre. Ellentétes paraeleme az elemi hő.\n\nFagy teremtése: A varázsló elemi fagyot teremt, és a kívánt formába foglalja. Az azon belül eső területen hűvös van, fokozott erősítés során fagy jön létre. A hőmérséklet E-nként −10 °C, függetlenül a természetes hőmérséklettől. A sebzés körönként −40 °C-nál jelentkezik (1 Sp), és innen kezdve minden további teljes 20 °C-onként 1 Sp-vel nő.", "feny": "A tűz és a levegő paraeleme. Megidézve az adott területen minden pont olyan fényességű lesz, mint az elemi fény erőssége (így az árnyékok eltűnnek). Ellentétes paraeleme az elemi sötétség.\n\nFény teremtése: A varázsló a formázás megszabta területen és alakban elemi fényt teremt. Amennyiben az eredeti fényesség kisebb, akkor ott nem látszik, de a területen mindenhol az adott fényesség lesz minimum, így például az árnyékok eltűnnek.\n\n1 E: gyertya lángja\n2 E: apró gyertya lángja\n3 E: olvasógyertya lángja\n4 E: templomi gyertya lángja\n5 E: mécses lángja\n6 E: fáklya lángja\n7 E: nagy fáklya lángja\n8 E: tábortűz fénye\n9 E: máglya fénye\n10 E: alkonyi fény\n11 E: napfény borús időben\n12 E: fátyolos napfény\n13 E: napsütés\n14 E: déli verőfény\n15+ E: vakító fény\n20+ E: nyitott szem esetén végleges vakság\n\nAz elemi fény azt a területet, ahol érvényesül, a fenti táblázat szerint világítja meg. Ezt a természeti hatások nem befolyásolhatják, kizárólag az elemi sötét! Ha a természetes fény erőssége nagyobb a paraeleménél, akkor ez utóbbinak a jelenlétét észre sem vesszük.", "setet": "A víz és a föld paraeleme. Megidézve az adott területen elnyeli a fényt, minden pontban olyan sötét lesz, mint ami az erősségnek megfelel. Ellentétes paraeleme az elemi fény.\n\nSötét teremtése: Hasonló a fény teremtéséhez, úgy szerencsés elképzelni, akár valami negatív, fekete fényt.\n\n1 E: alkonyat\n2 E: telihold\n3 E: fogyóhold\n4 E: újhold\n5 E: csillagos éjszaka\n6 E: borús éjszaka\n7 E: éjszaka kivilágítatlan szobában\n8 E: barlangban\n9 E: vaksötét\n10 E: kráni sötétség\n11+ E: ultra- és infralátás sem működik\n\nA területen, ahol az elemi sötét érvényesül, a fenti táblázat mutatta fényviszonyok érvényesülnek, függetlenül a természetes fénytől. Az elemi sötétet csak az elemi fény világíthatja be, a lámpások és a fáklyák világa vagy akár a nap ehhez nem elegendő, fényük nem is látszik, csak a hőhatásuk érvényesül."}}, {"id": "form", "label": "Forma", "type": "form"}], "source": "Part 10a"}'::jsonb);
INSERT INTO mosaics (id, name, school, subgroup, tier, status_state, cost_pattern, source, definition) VALUES ('anyagi-elemi-elemi-ero-idezese', 'Elemi erő idézése', 'anyagi', 'elemi', 3, 'complete', 'flat', 'Part 10a', '{"id": "anyagi-elemi-elemi-ero-idezese", "name": "Elemi erő idézése", "school": "anyagi", "subgroup": "elemi", "tier": 3, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "casting", "time": {"kind": "time", "amounts": {"sz": 1}}}, "duration": {"kind": "formDependent"}, "range": {"kind": "zone"}, "resistance": {"kind": "armorSfe"}, "power": {"unit": "E", "baseE": 1, "step": {"mp": 1, "e": 1}}, "cost": {"pattern": "flat", "baseMp": 1}, "inputs": [{"id": "form", "label": "Forma", "type": "form"}], "effect": "A mágikus energiákat felhasználva mozgatni vagy megállítani lehet tárgyakat.\n\nElemi erő teremtése: A varázsló olyan mennyiségű elemi erőt teremt, amely képes megtartani 5 kg súlyú vagy ugyanekkora erővel nekifeszülő tárgyat; avagy semlegesíteni 1 Sp-t, akár egy vért SFÉ-jét. Ez utóbbi leginkább aurára való formázás esetén fordul elő.\n\nálló súly (-): 1 E elemi erő 5 kg-ot tart meg\nséta (×2): 2,5 kg\nfutás (×5): 1 kg\nvágta (×10): 0,5 kg\n\nA súlyváltozás megmutatja, hogy az adott sebességgel haladó tárgy súlya mennyivel számít nagyobbnak, amikor az elemi erőnek ütközik. Az „1 E elemi erő megtart” oszlop megadja, hogy mekkora súlyt képes megtartani 1 E elemi erő, ha az a megadott sebességgel ütközik neki. Ha a súly meghaladja az elemi erő megtartó képességét, az semmilyen hatást nem fejt ki ellene.\n\nAz elemi erőből teremtett nyíl annyi Sp-t (sebzés pontot) sebez, mint amennyi az E-je (ereje), vagyis amennyit a hasonló, valódi anyagból való fegyver is sebezne.\nKitörés esetén az epicentrumban annyi Sp-t sebez, amennyi az E-je, kifelé távolodva negyedméterenként eggyel kevesebbet; nagy erősítés esetén feldönti a tárgyakat, embereket, kicsavarja a fákat, bokrokat.\nAz elemi erőből létrehozott szőnyeg E-nként 5 kg súlyt képes megtartani.\nA fal ugyanennyi súlyú nekifeszülő terhet tart távol, nem engedvén azt át magán.", "source": "Part 10a"}'::jsonb);
INSERT INTO mosaics (id, name, school, subgroup, tier, status_state, cost_pattern, source, definition) VALUES ('anyagi-elemi-elemental-idezes', 'Elementál idézés', 'anyagi', 'elemi', 4, 'incomplete', 'undefined', 'Part 10a', '{"id": "anyagi-elemi-elemental-idezes", "name": "Elementál idézés", "school": "anyagi", "subgroup": "elemi", "tier": 4, "status": {"state": "incomplete", "missing": ["cost", "duration", "range"]}, "castingTime": {"label": "casting", "time": {"kind": "time", "amounts": {"sz": 1}}}, "duration": {"kind": "undefined"}, "range": {"kind": "undefined"}, "resistance": {"kind": "none"}, "power": {"unit": "E", "baseE": 1, "step": null}, "cost": {"pattern": "undefined"}, "inputs": [], "source": "Part 10a"}'::jsonb);
INSERT INTO mosaics (id, name, school, subgroup, tier, status_state, cost_pattern, source, definition) VALUES ('anyagi-elemi-elemi-vedelem', 'Elemi védelem', 'anyagi', 'elemi', 4, 'complete', 'flat', 'Part 10a', '{"id": "anyagi-elemi-elemi-vedelem", "name": "Elemi védelem", "school": "anyagi", "subgroup": "elemi", "tier": 4, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "casting", "time": {"kind": "time", "amounts": {"sz": 1}}}, "duration": {"kind": "formDependent"}, "range": {"kind": "zone"}, "resistance": {"kind": "none"}, "power": {"unit": "E", "baseE": 1, "step": {"mp": 10, "e": 1}}, "cost": {"pattern": "flat", "baseMp": 10}, "inputs": [{"id": "form", "label": "Forma", "type": "form"}], "source": "Part 10a"}'::jsonb);
INSERT INTO mosaics (id, name, school, subgroup, tier, status_state, cost_pattern, source, definition) VALUES ('anyagi-term-atformazas', 'Átformázás', 'anyagi', 'termeszetes', 2, 'complete', 'compositionPerMass', 'Part 10b', '{"id": "anyagi-term-atformazas", "name": "Átformázás", "school": "anyagi", "subgroup": "termeszetes", "tier": 2, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "casting", "time": {"kind": "time", "amounts": {"sz": 4}}}, "duration": {"kind": "time", "time": {"kind": "time", "amounts": {"kor": 2}}}, "range": {"kind": "zone"}, "resistance": {"kind": "naturalMaterialMagic"}, "power": null, "cost": {"pattern": "compositionPerMass", "rounding": null, "rates": {"I": {"mp": 1, "massG": 1000}, "II": {"mp": 1, "massG": 500}, "III": {"mp": 1, "massG": 1}}}, "inputs": [{"id": "composition", "label": "Összetétel", "type": "composition"}], "effect": "A varázslattal egy tárgy FORMÁJÁT és SZÍNÉT változtathatja meg a varázsló. 1 Mp-ért az anyagcsoporttól függően 1 kg (I. csoport), 0,5 kg (II. csoport), vagy 1g (III. csoport) anyag formázható át. A varázslatban egyfajta súly- és anyagmegmaradási törvény érvényesül: azaz: pontosan a kiindulásival azonos súlyú és minőségű tárgy keletkezik. Ha kevesebb, akkor az új tárgy kialakításához fel nem használt anyag felesleg formájában megmarad. Az alapanyagnál nagyobb súlyú tárgy nem formázható.\n\nTöbb különálló tárgy is szolgáltathat alapanyagot a megformázni kívánt egyetlen holmihoz. Ilyenkor azok összeolvadnak. Ha eleve több különböző minőségű anyagból álló tárgyat kívánunk átformázni, akkor a végtermékben is érvényesül azok egymáshoz viszonyított aránya.\n\nHa a varázslat időtartama lejár, a tárgy visszaalakul eredeti formájára.\n\nPélda: sárga gömb helyett kék négyzet.", "source": "Part 10b"}'::jsonb);
INSERT INTO mosaics (id, name, school, subgroup, tier, status_state, cost_pattern, source, definition) VALUES ('anyagi-term-atalakitas', 'Átalakítás', 'anyagi', 'termeszetes', 2, 'complete', 'compositionPerMass', 'Part 10b', '{"id": "anyagi-term-atalakitas", "name": "Átalakítás", "school": "anyagi", "subgroup": "termeszetes", "tier": 2, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "casting", "time": {"kind": "time", "amounts": {"sz": 6}}}, "duration": {"kind": "time", "time": {"kind": "time", "amounts": {"kor": 2}}}, "range": {"kind": "zone"}, "resistance": {"kind": "naturalMaterialMagic"}, "power": null, "cost": {"pattern": "compositionPerMass", "rounding": null, "rates": {"I": {"mp": 1, "massG": 1000}, "II": {"mp": 1, "massG": 500}, "III": {"mp": 1, "massG": 1}}}, "inputs": [{"id": "composition", "label": "Összetétel", "type": "composition"}], "effect": "A varázsló az anyag MINŐSÉGÉT változtathatja meg, de csak az adott anyagcsoporton belül. A tárgy halmazállapota, formája nem változik, színe is csak akkor, ha ezt az anyagminőség változása indokolttá teszi. Az átalakítás során az anyag térfogata mérvadó: pontosan ugyanakkora és ugyanolyan formájú marad, ám a súlya megváltozik. A varázslat 1 kg (I), 1/2 kg (II) vagy 1g (III) anyag átalakítására használható.\n\nSzigorú megkötés, hogy a varázsló csak olyan anyaggá képes bármit is átalakítani, amelynek összetételét ismeri. Pl. méreggé való átalakításhoz bírnia kell a Méregkeverés vagy az alkímia, netán a herbalizmus képzettséggel.\n\nA varázslattal élőlények is átalakíthatók bármilyen I. csoportba tartozó anyaggá (pl. kővé változtatás). Vagy éppen fordítva, sárból is gyúrható élőlény teste, ám az efféle teremtmény nem fogja magában hordozni az élet princípiumát, ezért nem számít élőlénynek csak homonkulusznak.\n\nHa a varázslat időtartama lejár, a tárgy visszanyeri eredeti minőségét.\n\nAz Mp igény kiszámításánál a kiindulási tárgy súlya a mérvadó, nem a keletkezetté.\n\nAnyagcsoporton belül, pl. kővé változtatás.", "source": "Part 10b"}'::jsonb);
INSERT INTO mosaics (id, name, school, subgroup, tier, status_state, cost_pattern, source, definition) VALUES ('anyagi-term-teremtes', 'Teremtés', 'anyagi', 'termeszetes', 3, 'complete', 'compositionPerMass', 'Part 10b', '{"id": "anyagi-term-teremtes", "name": "Teremtés", "school": "anyagi", "subgroup": "termeszetes", "tier": 3, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "casting", "time": {"kind": "time", "amounts": {"sz": 3}}}, "duration": {"kind": "oneOff"}, "range": {"kind": "zone"}, "resistance": {"kind": "naturalMaterialMagic"}, "power": null, "cost": {"pattern": "compositionPerMass", "rounding": null, "rates": {"I": {"mp": 5, "massG": 1000}, "II": {"mp": 5, "massG": 500}, "III": {"mp": 5, "massG": 1}}}, "inputs": [{"id": "composition", "label": "Összetétel", "type": "composition"}], "effect": "Nem volt – van.", "source": "Part 10b"}'::jsonb);
